// Helper function to count positive integers in a sequence
function CountPositive(l: seq<int>): int
    requires l != null
    ensures CountPositive(l) >= 0
{
    var count := 0;
    var i := 0;
    while i < |l|
        invariant 0 <= count <= i
        invariant i <= |l|
    {
        if l[i] > 0 {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

